import{_ as s,o as e,c as t,a0 as i}from"./chunks/framework.1R7PBCUH.js";const g=JSON.parse('{"title":"Package Management","description":"","frontmatter":{},"headers":[],"relativePath":"labs/package-management.md","filePath":"labs/package-management.md"}'),n={name:"labs/package-management.md"};function o(l,a,p,h,d,c){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="package-management" tabindex="-1">Package Management <a class="header-anchor" href="#package-management" aria-label="Permalink to &quot;Package Management&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>This lab is still in draft. It contains all the information you need, but the text isn&#39;t polished yet.</p></div><p>In this lab, you&#39;ll learn how to use a <strong>package manager</strong> to install and manage the software on your system.</p><h2 id="binaries-and-packages" tabindex="-1">Binaries and packages <a class="header-anchor" href="#binaries-and-packages" aria-label="Permalink to &quot;Binaries and packages&quot;">​</a></h2><p>When you compile the source code for a program, the compiler outputs an executable file known as a <strong>binary</strong>. This binary is then bundled with the assets, libraries, configuration files, and documentation for the program into a <strong>package</strong>.</p><p>Linux distributions include a vast selection of packages, and a <strong>package manager</strong> to add, upgrade, or remove these packages.</p><p>A package manager knows where to install the contents of a package, tracks which file belongs to which package, and understands the dependencies between packages.</p><p>You&#39;ll start this lab by installing a package without the help of a package manager. This experience will help you understand and appreciate what a package manager does.</p><h2 id="installing-software-manually" tabindex="-1">Installing software manually <a class="header-anchor" href="#installing-software-manually" aria-label="Permalink to &quot;Installing software manually&quot;">​</a></h2><p>As an example, you&#39;ll install <a href="https://github.com/bootandy/dust" target="_blank" rel="noreferrer">Dust</a>, a small tool for visualizing disk usage, similar to <code>du</code>.</p><p>Start by navigating to your <strong>Downloads</strong> directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads</span></span></code></pre></div><p>Dust publishes its releases on <a href="https://github.com/bootandy/dust/releases" target="_blank" rel="noreferrer">GitHub</a>. Some of these are premade Ubuntu packages, but most are compressed archives for various platforms (including Windows and macOS).</p><p>For this example, you&#39;ll use a <strong>tarball</strong>, which is an old archiving and compression format for Linux. It combines the <strong><code>tar</code></strong> (<em>tape archive</em>) and <strong><code>gzip</code></strong> formats into a single file with the <strong>.tar.gz</strong> extension.</p><p>You&#39;ll use <strong><code>wget</code></strong> to download the file you need straight from the command line.</p><p>If your computer uses the Intel/AMD 64-bit architecture (<strong>x86_64</strong>), run the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/bootandy/dust/releases/download/v1.2.6/dust-v1.2.6-x86_64-unknown-linux-gnu.tar.gz</span></span></code></pre></div><p>For the ARM 64-bit architecture (<strong>AArch64</strong>), use the following command instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/bootandy/dust/releases/download/v1.2.6/dust-v1.2.6-aarch64-unknown-linux-gnu.tar.gz</span></span></code></pre></div><p>Next, extract the contents of the tarball:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dust-v1.2.6-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-unknown-linux-gnu.tar.gz</span></span></code></pre></div><p>This command tells <code>tar</code> to read the file (<code>-f</code>) you specified as an argument, unzip it (<code>-z</code>), and extract (<code>-x</code>) its contents.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>I used globbing so the command will work on any machine, regardless of its architecture. However, you can just press <code>Tab</code> after typing <code>dust</code> and Bash will autocomplete the rest of the filename for you.</p></div><p>The archive contained a directory named <strong>dust-v1.2.6-x86_64-unknown-linux-gnu</strong> or <strong>dust-v1.2.6-aarch64-unknown-linux-gnu</strong>. Inspect the contents of this directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dust-v1.2.6-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-unknown-linux-gnu</span></span></code></pre></div><p>You&#39;ll see three files, one of which is a binary executable named <strong>dust</strong>. Run this binary to try it out:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dust-v1.2.6-*-unknown-linux-gnu/dust</span></span></code></pre></div><p><code>dust</code> will show the contents of the current directory and how much space they take up.</p><p>To install <code>dust</code>, you need to move the executable to a location where Bash knows to look for it. The <code>PATH</code> environment variable lists these locations:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $PATH</span></span></code></pre></div><p>Whenever you type a command, Bash goes through the directories on your <code>PATH</code>, from left to right, until it finds a match. If it doesn&#39;t, it will report this as an error. That&#39;s why earlier, you specified the <em>path</em> to the executable (not just its name) so Bash knows where to find it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dust-v1.2.6-*-unknown-linux-gnu/dust</span></span></code></pre></div><p>To install <code>dust</code>, copy or move its executable to <strong>/usr/local/bin</strong>, which is the appropriate home for it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dust-v1.2.6-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-unknown-linux-gnu/dust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin</span></span></code></pre></div><p>This command will fail because, as a regular user, you&#39;re not allowed to modify files outside of your home directory. Rerun the previous command with <strong><code>sudo</code></strong> to elevate your permissions to that of a system administrator:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dust-v1.2.6-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-unknown-linux-gnu/dust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin</span></span></code></pre></div><p>Alternatively, use the double exclamation point (<code>!!</code>) to recall the previous command from your history, and add <code>sudo</code> in front:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> !!</span></span></code></pre></div><p>You&#39;ll find this quite useful, as it&#39;s common to forget <code>sudo</code> when you need it.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>You&#39;ll learn more about <code>sudo</code> in the next lab, <a href="./users-and-permissions.html">Users and Permissions</a>.</p></div><p>Now that <code>dust</code> is installed, you can run it from anywhere on your system:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dust</span></span></code></pre></div><p>Try it out, then uninstall <code>dust</code> by removing its executable from <strong>/usr/local/bin</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/dust</span></span></code></pre></div><p>In the next section, you&#39;ll reinstall <code>dust</code> using a package manager.</p><h2 id="using-a-package-manager" tabindex="-1">Using a package manager <a class="header-anchor" href="#using-a-package-manager" aria-label="Permalink to &quot;Using a package manager&quot;">​</a></h2><p>If the previous section felt like a lot of work, that&#39;s because it was. In most cases, a manual installation process is even more complicated: packages can include many more files that need to go into specific directories, and can depend on other packages that should be installed first. Fortunately, a package manager handles all of this for you.</p><p>Ubuntu is based on <a href="https://www.debian.org" target="_blank" rel="noreferrer">Debian</a> and uses the Debian package format (<strong>.deb</strong>), the Debian Package tool (<strong><code>dpkg</code></strong>), and the Advanced Package Tool (<strong><code>apt</code></strong>). The latter is what you&#39;ll use for most package management tasks.</p><p>Before you do anything with <code>apt</code>, update your local package database so <code>apt</code> is aware of the latest available versions of each package:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>Next, search for the package you want to install:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dust</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">Note</p><p>Searching doesn&#39;t modify your system so it doesn&#39;t require elevated permissions (<code>sudo</code>).</p></div><p>Scroll through the list. You&#39;ll find <code>dust</code> as <code>du-dust</code>.</p><p>Install <code>dust</code> with the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> du-dust</span></span></code></pre></div><p>This one command is all you need. <code>apt</code> will find the correct package for your architecture, check for and install any dependencies, and extract the contents of the package to the appropriate directories.</p><p><code>dpkg</code> can list the files that were installed as part of this package:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> du-dust</span></span></code></pre></div><p>Among the files you should recognize are the executable <strong>/usr/bin/dust</strong> and the man page <strong>/usr/share/man/man1/dust.1.gz</strong>.</p><p>All of these files will be removed when you uninstall the package:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> du-dust</span></span></code></pre></div><p>For more information about <code>apt</code>, consult its man page. You&#39;ll find that <code>apt</code> has many more useful subcommands, such as <code>show</code>, <code>list</code>, <code>upgrade</code>, and <code>remove</code>.</p><h2 id="self-contained-packages" tabindex="-1">Self-contained packages <a class="header-anchor" href="#self-contained-packages" aria-label="Permalink to &quot;Self-contained packages&quot;">​</a></h2><p>Traditional package managers such as <code>apt</code> are deeply integrated with the system and offer the best possible performance. However, this performance comes with some drawbacks. For example, packages often have conflicting dependencies, requiring different versions of the same library. Also, any package you install has full access to all of your files and directories, which is a potential security risk. For these reasons, newer package managers use <strong>self-contained</strong> packages, similar to how applications work on mobile platforms with app stores.</p><p>Self-contained packages require additional memory and storage, making them much less efficient than traditional packages, but they do offer some benefits. A self-contained package can include all of its dependencies, making it compatible with many more operating systems and versions. A self-contained package is also <strong>sandboxed</strong>, meaning it&#39;s isolated from the rest of the system. Sandboxed applications have a limited set of permissions that have to be requested by the developer and granted by the user. Without these permissions, the application cannot open any files, use the network, or access any devices.</p><p>Ubuntu uses <strong><code>snap</code></strong> for self-contained packages, whereas most other distributions use <strong><code>flatpak</code></strong>. In the following sections, you&#39;ll use <code>snap</code> to install <strong>GIMP</strong>, and <code>flatpak</code> to install <strong>Inkscape</strong>. GIMP and Inkscape are popular open source alternatives to Adobe Photoshop and Illustrator.</p><h3 id="installing-a-package-with-snap" tabindex="-1">Installing a package with snap <a class="header-anchor" href="#installing-a-package-with-snap" aria-label="Permalink to &quot;Installing a package with snap&quot;">​</a></h3><p><code>snap</code> powers the <strong>App Center</strong> that you used in <a href="./../exercises/exercises1.html#appcenter">Exercise 1.3</a>. You can use this application to browse the <a href="https://snapcraft.io/store" target="_blank" rel="noreferrer">Snap Store</a> and install or remove packages, but in this lab, you&#39;ll use the command line instead.</p><p>Search for “gimp” to find the package you want to install:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">snap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gimp</span></span></code></pre></div><p>Install this package as follows:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gimp</span></span></code></pre></div><p>Once GIMP is installed, you can click its icon in the Applications Overview, or run it from the command line:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gimp</span></span></code></pre></div><p>For more information about <code>snap</code>, consult its man page and look up the subcommands <code>info</code>, <code>list</code>, <code>refresh</code>, and <code>remove</code>.</p><h3 id="installing-a-package-with-flatpak" tabindex="-1">Installing a package with flatpak <a class="header-anchor" href="#installing-a-package-with-flatpak" aria-label="Permalink to &quot;Installing a package with flatpak&quot;">​</a></h3><p>Ubuntu doesn&#39;t include <code>flatpak</code> out of the box, but you can install it using <code>apt</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flatpak</span></span></code></pre></div><p>Unlike <code>snap</code>, which is tied to the <a href="https://snapcraft.io/store" target="_blank" rel="noreferrer">Snap Store</a>, <code>flatpak</code> is decentralized and lets you download packages from any store. You first have to register one or more stores before you can start using it.</p><p>Use the following command to register <a href="https://flathub.org/en" target="_blank" rel="noreferrer">Flathub</a>, a popular store for <code>flatpak</code> packages:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flathub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://dl.flathub.org/repo/flathub.flatpakrepo</span></span></code></pre></div><p>Restart your system (or sign out and back in) for this change to take effect, then confirm that Flathub has been registered:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remotes</span></span></code></pre></div><p>You can now search for “inkscape” to find the package you want to install:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inkscape</span></span></code></pre></div><p>Find the correct <strong>Application ID</strong> and use this ID to install the package:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.inkscape.Inkscape</span></span></code></pre></div><p>This will install Inkscape and any dependencies it requires.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p><code>flatpak</code> is designed to not require <code>sudo</code>. Instead, it will prompt you for your password whenever it needs additional permissions.</p></div><p>Once Inkscape is installed, you can click its icon in the Applications Overview, or run it from the command line:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.inkscape.Inkscape</span></span></code></pre></div><p>As you can see, this is very different from how you run <code>snap</code> packages. <code>snap</code> installs binaries in <strong>/snap/bin</strong>, which is listed in the <code>PATH</code> variable, whereas <code>flatpak</code> applications are more heavily sandboxed and invoked through <code>flatpak</code> itself.</p><p>For more information about <code>flatpak</code>, consult its man page and look up the subcommands <code>info</code>, <code>list</code>, <code>update</code>, and <code>uninstall</code>.</p><h2 id="up-next" tabindex="-1">Up next <a class="header-anchor" href="#up-next" aria-label="Permalink to &quot;Up next&quot;">​</a></h2><p>This lab briefly touched on permissions when discussing <code>sudo</code>. In the next lab, you&#39;ll learn how Linux handles users, groups, and permissions.</p>',96)])])}const u=s(n,[["render",o]]);export{g as __pageData,u as default};
